#!/usr/bin/env bash
# Recoverable snapshot of the local design pilot: database dump, the pieces that
# are NOT in git (fides-template-pilot, fides-vocabulary-glossary, blocksy-child,
# the guard mu-plugin) and a version manifest. wp-config.php and uploads are not
# copied: the config holds secrets and is regenerated by setup-site.sh.
# Output: pilot-backup/snapshots/<timestamp>/ (run restore-check.sh afterwards).
set -euo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/env.sh"

STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="${BACKUP_OUT:-$PILOT_ROOT/pilot-backup/snapshots/$STAMP}"
mkdir -p "$OUT/non-git/plugins" "$OUT/non-git/themes" "$OUT/non-git/mu-plugins"

"$MYSQL_BIN_DIR/mysqldump" -uroot -proot -S "$MYSQL_SOCK" --single-transaction --default-character-set=utf8mb4 \
  "$PILOT_DB" 2> >(grep -v 'Using a password' >&2) | gzip -9 > "$OUT/db.sql.gz"

WP_CONTENT="$PILOT_SITE/wp-content"
for plugin in fides-template-pilot fides-vocabulary-glossary; do
  if [[ -d "$WP_CONTENT/plugins/$plugin" && ! -L "$WP_CONTENT/plugins/$plugin" ]]; then
    rsync -a "$WP_CONTENT/plugins/$plugin/" "$OUT/non-git/plugins/$plugin/"
  fi
done
rsync -a "$WP_CONTENT/themes/blocksy-child/" "$OUT/non-git/themes/blocksy-child/"
rsync -a "$WP_CONTENT/mu-plugins/" "$OUT/non-git/mu-plugins/"

{
  echo "snapshot: $STAMP"
  echo "database: $PILOT_DB"
  echo "-- wordpress"
  pilot_wp core version
  echo "-- plugins (name status version)"
  pilot_wp plugin list --fields=name,status,version --format=csv
  echo "-- themes"
  pilot_wp theme list --fields=name,status,version --format=csv
  echo "-- git worktrees (branch commit)"
  for repo in credential-catalog use-case-catalog fides-community-tools-tiles organization-catalog wallet-catalog; do
    echo "$repo $(git -C "$PILOT_ROOT/$repo" rev-parse --abbrev-ref HEAD) $(git -C "$PILOT_ROOT/$repo" rev-parse --short HEAD) dirty=$(git -C "$PILOT_ROOT/$repo" status --porcelain | wc -l | tr -d ' ')"
  done
} > "$OUT/MANIFEST.txt"
(cd "$OUT" && find . -type f ! -name SHA256SUMS -print0 | sort -z | xargs -0 shasum -a 256 > SHA256SUMS)
echo "Snapshot written: $OUT"
echo "Next: restore-check.sh \"$OUT\""
